def donut(parts, size=62, hole=0.58):
    tot = sum(v for _, v, _ in parts)
    acc = 0; stops = []
    for n, v, c in parts:
        a0 = acc / tot * 360; acc += v; a1 = acc / tot * 360
        stops.append(f'{c} {a0:.2f}deg {a1:.2f}deg')
    return (f'<div style="width:{size}mm;height:{size}mm;border-radius:50%;background:conic-gradient({", ".join(stops)});position:relative">'
            f'<div style="position:absolute;inset:{size*(1-hole)/2:.1f}mm;background:#fff;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center">'
            f'<div class="mt" style="font:800 {size*0.22:.0f}pt/1 Montserrat;font-variant-numeric:tabular-nums">{tot}</div><div style="font:700 6.4pt Arial;color:#5B5670">dossiers</div></div></div>')

def legend(parts, fs=8.2):
    tot = sum(v for _, v, _ in parts)
    return ''.join(f'<div style="display:flex;align-items:center;gap:2.4mm;font:400 {fs}pt Arial;margin:1.8mm 0"><i style="width:3.4mm;height:3.4mm;border-radius:.8mm;background:{c};display:inline-block;flex:none"></i><span style="flex:1">{n}</span><b style="font-variant-numeric:tabular-nums">{v}</b><span style="color:#5B5670;width:11mm;text-align:right">{round(v/tot*100)} %</span></div>' for n, v, c in parts)

def hbars(rows, maxv, color='#0433C3', fs=8):
    return ''.join(f'<div style="display:flex;align-items:center;gap:3mm;margin:1.9mm 0;font:400 {fs}pt Arial"><div style="width:30mm;text-align:right">{n}</div><div style="flex:1;background:#F0EAF2;border-radius:.8mm"><div style="width:{v/maxv*100:.0f}%;height:5.4mm;background:{color};border-radius:.8mm"></div></div><b style="width:10mm;font-variant-numeric:tabular-nums">{v}</b></div>' for n, v in rows)

def line(vals, w=140, h=60, color='#0433C3', labels=None):
    mx = max(vals) * 1.15; n = len(vals)
    pts = [(8 + i * (w - 14) / (n - 1), h - 8 - v / mx * (h - 16)) for i, v in enumerate(vals)]
    grid = ''.join(f'<line x1="8" x2="{w-4}" y1="{h-8-k*(h-16)/4:.1f}" y2="{h-8-k*(h-16)/4:.1f}" stroke="#E4DCE6" stroke-width=".25"/>' for k in range(5))
    poly = ' '.join(f'{x:.1f},{y:.1f}' for x, y in pts)
    dots = ''.join(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="1.1" fill="{color}"/>' for x, y in pts)
    lab = (f'<text x="{pts[0][0]:.1f}" y="{pts[0][1]-3:.1f}" font-size="3.4" font-family="Arial" font-weight="700" fill="#1B1630">{vals[0]}</text>'
           f'<text x="{pts[-1][0]-4:.1f}" y="{pts[-1][1]-3:.1f}" font-size="3.4" font-family="Arial" font-weight="700" fill="{color}">{vals[-1]}</text>')
    xl = ''.join(f'<text x="{x:.1f}" y="{h-1.5}" font-size="3" font-family="Arial" fill="#5B5670" text-anchor="middle">{m}</text>' for (x, _), m in zip(pts, labels or []))
    return f'<svg viewBox="0 0 {w} {h}" style="width:100%;height:auto">{grid}<polyline points="{poly}" fill="none" stroke="{color}" stroke-width="1.1" stroke-linejoin="round" stroke-linecap="round"/>{dots}{lab}{xl}</svg>'

DEPTS = [('Atacora', 0, 0, 38), ('Alibori', 1, 0, 24), ('Donga', 0, 1, 41), ('Borgou', 1, 1, 77), ('Collines', 1, 2, 52), ('Couffo', 0, 3, 3), ('Zou', 1, 3, 69), ('Plateau', 2, 3, 46), ('Mono', 0, 4, 29), ('Atlantique', 1, 4, 118), ('Ouémé', 2, 4, 88), ('Littoral', 1, 5, 131)]

def tilemap(cell=24, show_vals=True):
    def shade(v):
        if v < 5: return ('#fff', '#8E88A0', 'repeating-linear-gradient(45deg,#F6F2F7 0 2mm,#E4DCE6 2mm 4mm)')
        t = min(v / 131, 1)
        steps = ['#EBEFFA', '#AFBEEC', '#4366D2', '#032BA6', '#02134A']
        bg = steps[min(int(t * 5), 4)]
        fg = '#1B1630' if bg in ('#EBEFFA', '#AFBEEC') else '#fff'
        return (bg, fg, bg)
    tiles = ''
    for n, c, r, v in DEPTS:
        bg, fg, bgi = shade(v)
        val = 'masqué' if v < 5 else str(v)
        tiles += (f'<div style="position:absolute;left:{c*(cell+2)}mm;top:{r*(cell*0.78+2)}mm;width:{cell}mm;height:{cell*0.78}mm;background:{bgi};color:{fg};border-radius:1.6mm;display:flex;flex-direction:column;align-items:center;justify-content:center;border:.2mm solid #d8cfdc">'
                  f'<div class="mt" style="font:800 7.6pt Montserrat">{n}</div><div style="font:700 6.6pt Arial;font-variant-numeric:tabular-nums">{val if show_vals else ""}</div></div>')
    return f'<div style="position:relative;width:{3*(cell+2)}mm;height:{6*(cell*0.78+2)}mm">{tiles}</div>'

